const flashcardsTO: { cat: string; q: string; a: string }[] = [{"cat": "Anatomia Humana", "q": "Qual plano divide o corpo em anterior e posterior?", "a": "Plano coronal ou frontal."}, {"cat": "Anatomia Humana", "q": "Qual plano mediano divide o corpo?", "a": "Em metades direita e esquerda."}, {"cat": "Anatomia Humana", "q": "O que significa proximal?", "a": "Mais próximo da origem ou raiz de um membro."}, {"cat": "Anatomia Humana", "q": "Quantos lobos tem o pulmão direito?", "a": "Três lobos."}, {"cat": "Anatomia Humana", "q": "Quantos lobos tem o pulmão esquerdo?", "a": "Dois lobos."}, {"cat": "Anatomia Humana", "q": "Onde se localiza o coração?", "a": "Principalmente no mediastino médio."}, {"cat": "Anatomia Humana", "q": "Por que o plano mediano é diferente de qualquer plano sagital?", "a": "Porque o plano mediano passa exatamente pela linha média e divide o corpo em metades direita e esquerda; planos sagitais podem ser paralelos a ele sem produzir metades iguais."}, {"cat": "Anatomia Humana", "q": "Qual relação anatômica existe entre o nervo frênico e a raiz do pulmão?", "a": "O nervo frênico passa anteriormente à raiz pulmonar; o nervo vago passa posteriormente."}, {"cat": "Anatomia Humana", "q": "Por que o brônquio principal direito recebe corpos aspirados com maior frequência?", "a": "Porque tende a ser mais curto, mais largo e mais vertical que o esquerdo."}, {"cat": "Anatomia Humana", "q": "O que diferencia proximal de superior em um membro?", "a": "Proximal descreve distância em relação à raiz do membro; superior descreve posição em relação à cabeça."}, {"cat": "Anatomia Humana", "q": "Qual compartimento do mediastino contém o coração envolvido pelo pericárdio?", "a": "O mediastino médio."}, {"cat": "Anatomia Humana", "q": "Por que um procedimento intercostal evita a borda inferior da costela superior?", "a": "Porque o feixe neurovascular intercostal principal percorre o sulco costal nessa borda."}, {"cat": "Histologia", "q": "Uma característica geral do epitélio?", "a": "Células justapostas e pouca matriz extracelular."}, {"cat": "Histologia", "q": "O epitélio é vascularizado?", "a": "Não; recebe nutrientes por difusão."}, {"cat": "Histologia", "q": "Função das microvilosidades?", "a": "Aumentar a superfície de absorção."}, {"cat": "Histologia", "q": "Principal célula produtora de matriz conjuntiva?", "a": "Fibroblasto."}, {"cat": "Histologia", "q": "Função importante do macrófago?", "a": "Fagocitose e coordenação da resposta inflamatória."}, {"cat": "Histologia", "q": "Que fibra dá resistência à tração?", "a": "Principalmente fibras colágenas."}, {"cat": "Histologia", "q": "Como se classifica um epitélio estratificado?", "a": "Pelo formato das células da camada mais superficial, e não pelo formato das células basais."}, {"cat": "Histologia", "q": "Qual é a diferença funcional entre desmossomos e junções oclusivas?", "a": "Desmossomos fornecem resistência mecânica entre células; junções oclusivas controlam passagem paracelular e ajudam a manter polaridade."}, {"cat": "Histologia", "q": "Por que o epitélio depende do tecido conjuntivo subjacente para nutrição?", "a": "Porque epitélios são avasculares e recebem nutrientes por difusão a partir de vasos do conjuntivo."}, {"cat": "Histologia", "q": "Qual componente da matriz dá grande resistência à tração?", "a": "Fibras colágenas, especialmente colágeno tipo I em muitos tecidos conjuntivos."}, {"cat": "Histologia", "q": "O que diferencia tecido conjuntivo frouxo do denso?", "a": "Principalmente a proporção e organização das fibras em relação a células e substância fundamental."}, {"cat": "Histologia", "q": "Por que a membrana basal é importante em patologia tumoral?", "a": "Porque a ultrapassagem da membrana basal marca invasão do epitélio para o estroma em diversos carcinomas."}, {"cat": "Biologia Celular", "q": "Qual bomba mantém gradientes de Na+ e K+?", "a": "Na+/K+-ATPase."}, {"cat": "Biologia Celular", "q": "Difusão facilitada usa o quê?", "a": "Canais ou proteínas carreadoras."}, {"cat": "Biologia Celular", "q": "Apoptose costuma causar inflamação intensa?", "a": "Não, geralmente não."}, {"cat": "Biologia Celular", "q": "Necrose preserva a membrana celular?", "a": "Não; há perda de integridade da membrana."}, {"cat": "Biologia Celular", "q": "Por que a Na+/K+-ATPase é essencial mesmo não gerando sozinha o potencial de repouso?", "a": "Porque mantém os gradientes de Na+ e K+ que permitem o potencial de repouso, transporte secundário e excitabilidade."}, {"cat": "Biologia Celular", "q": "Qual é a diferença entre transporte ativo primário e secundário?", "a": "O primário usa energia diretamente, geralmente ATP; o secundário utiliza a energia armazenada no gradiente de outro soluto."}, {"cat": "Biologia Celular", "q": "Por que transportadores podem apresentar saturação?", "a": "Porque possuem número finito de sítios e ciclos de transporte; quando todos estão ocupados, a velocidade aproxima-se de um limite."}, {"cat": "Biologia Celular", "q": "Qual proteína atua como importante freio do ciclo celular ao controlar E2F?", "a": "A proteína Rb."}, {"cat": "Biologia Celular", "q": "Como p53 pode impedir propagação de dano genético?", "a": "Promovendo parada do ciclo para reparo e, em dano grave, favorecendo senescência ou apoptose."}, {"cat": "Biologia Celular", "q": "Qual diferença morfológica central separa apoptose de necrose?", "a": "Na apoptose a membrana permanece relativamente íntegra e a célula fragmenta-se de forma organizada; na necrose há perda de integridade e extravasamento de conteúdo."}, {"cat": "Bioquímica Médica", "q": "O que representa Vmax?", "a": "Velocidade máxima com enzima saturada."}, {"cat": "Bioquímica Médica", "q": "O que representa Km no modelo clássico?", "a": "Substrato na metade da Vmax."}, {"cat": "Bioquímica Médica", "q": "Onde ocorre a glicólise?", "a": "No citosol."}, {"cat": "Bioquímica Médica", "q": "Principal destino aeróbio do piruvato?", "a": "Conversão em acetil-CoA."}, {"cat": "Bioquímica Médica", "q": "Por que uma enzima não altera o equilíbrio final de uma reação?", "a": "Porque reduz a energia de ativação das reações direta e reversa sem modificar a diferença de energia livre entre reagentes e produtos."}, {"cat": "Bioquímica Médica", "q": "Como uma inibição competitiva altera Km aparente e Vmax no modelo clássico?", "a": "Aumenta o Km aparente e mantém a Vmax, porque altas concentrações de substrato podem superar a competição."}, {"cat": "Bioquímica Médica", "q": "Por que o fígado consegue contribuir para a glicemia usando seu glicogênio, mas o músculo não?", "a": "Porque o fígado possui mecanismos para gerar glicose livre a partir de glicose-6-fosfato; o músculo usa seu glicogênio principalmente localmente."}, {"cat": "Bioquímica Médica", "q": "Qual é o papel metabólico do lactato no ciclo de Cori?", "a": "Ele transporta carbono de tecidos produtores para o fígado, onde pode ser convertido novamente em glicose pela gliconeogênese."}, {"cat": "Bioquímica Médica", "q": "Por que acetil-CoA não gera glicose líquida em humanos?", "a": "Porque seus carbonos entram no ciclo do ácido cítrico e são perdidos como CO2 sem uma via líquida que os converta em oxaloacetato para gliconeogênese."}, {"cat": "Bioquímica Médica", "q": "O que a regulação alostérica permite a uma via metabólica?", "a": "Alterar rapidamente a atividade de enzimas-chave em resposta a metabólitos, sem esperar mudança na quantidade de enzima."}, {"cat": "Fisiologia Cardiovascular", "q": "Como se calcula o débito cardíaco?", "a": "Frequência cardíaca × volume sistólico."}, {"cat": "Fisiologia Cardiovascular", "q": "Três determinantes do volume sistólico?", "a": "Pré-carga, contratilidade e pós-carga."}, {"cat": "Fisiologia Cardiovascular", "q": "O que descreve Frank-Starling?", "a": "Maior enchimento fisiológico aumenta força de contração."}, {"cat": "Fisiologia Cardiovascular", "q": "O que detectam barorreceptores?", "a": "Estiramento relacionado à pressão arterial."}, {"cat": "Fisiologia Cardiovascular", "q": "O que eleva a resistência vascular?", "a": "Redução do raio arteriolar."}, {"cat": "Fisiologia Cardiovascular", "q": "Qual sistema renal eleva retenção de sódio e vasoconstrição?", "a": "Sistema renina-angiotensina-aldosterona."}, {"cat": "Fisiologia Cardiovascular", "q": "Em qual fase do ciclo todas as valvas estão fechadas e a pressão ventricular sobe?", "a": "Na contração isovolumétrica."}, {"cat": "Fisiologia Cardiovascular", "q": "O que faz as valvas cardíacas abrirem ou fecharem?", "a": "Gradientes de pressão entre as câmaras e os grandes vasos, não uma contração ativa das valvas."}, {"cat": "Fisiologia Cardiovascular", "q": "Como o aumento de pré-carga pode elevar o volume sistólico pelo mecanismo de Frank-Starling?", "a": "O maior enchimento aumenta o comprimento inicial das fibras dentro de limites fisiológicos, permitindo maior geração de força."}, {"cat": "Fisiologia Cardiovascular", "q": "Por que a diástole é particularmente afetada pela taquicardia?", "a": "Porque, à medida que o ciclo encurta, a diástole reduz proporcionalmente mais, diminuindo o tempo de enchimento e de perfusão coronariana."}, {"cat": "Fisiologia Cardiovascular", "q": "Qual efeito imediato uma queda súbita da pressão arterial produz no barorreflexo?", "a": "Reduz disparos de barorreceptores e aumenta atividade simpática, com maior frequência, contratilidade e vasoconstrição."}, {"cat": "Fisiologia Cardiovascular", "q": "Por que reduzir o raio de uma arteríola aumenta muito a resistência?", "a": "Porque a resistência ao fluxo é extremamente sensível ao raio vascular; pequenas reduções produzem grande aumento de resistência."}, {"cat": "Fisiologia Respiratória", "q": "Principal músculo da inspiração tranquila?", "a": "Diafragma."}, {"cat": "Fisiologia Respiratória", "q": "Quem produz surfactante?", "a": "Pneumócitos tipo II."}, {"cat": "Fisiologia Respiratória", "q": "Função principal do surfactante?", "a": "Reduzir tensão superficial alveolar."}, {"cat": "Fisiologia Respiratória", "q": "Como é transportado a maior parte do O2?", "a": "Ligado à hemoglobina."}, {"cat": "Fisiologia Respiratória", "q": "Principal forma de transporte de CO2?", "a": "Bicarbonato."}, {"cat": "Fisiologia Respiratória", "q": "O que altera troca gasosa regional?", "a": "A relação ventilação-perfusão."}, {"cat": "Fisiologia Respiratória", "q": "O que é pressão transpulmonar?", "a": "A diferença entre a pressão alveolar e a pressão intrapleural, que atua como força distensora do pulmão."}, {"cat": "Fisiologia Respiratória", "q": "Por que o surfactante ajuda a evitar colapso alveolar?", "a": "Porque reduz a tensão superficial, especialmente em volumes menores, aumentando estabilidade e complacência."}, {"cat": "Fisiologia Respiratória", "q": "Qual é a diferença entre ventilação minuto e ventilação alveolar?", "a": "A ventilação minuto inclui todo o volume movimentado; a alveolar desconta o espaço morto e representa ar novo que chega às unidades de troca."}];

